  "tx-126": "Relación con la Tierra",
  "tx-127": "Abandono, colonización marciana, crecimiento infinito",
  "tx-128": "Anclaje absoluto en el Átomo-Tierra, gestión sobria de un sistema finito",
  "tx-129": "Rol del aumento",
